                    let guid_bytes = memory.read_bytes(guid_ptr, 16)?;
                    let guid_str = format!("{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
                        guid_bytes[0], guid_bytes[1], guid_bytes[2], guid_bytes[3],
                        guid_bytes[4], guid_bytes[5], guid_bytes[6], guid_bytes[7],
                        guid_bytes[8], guid_bytes[9], guid_bytes[10], guid_bytes[11],
                        guid_bytes[12], guid_bytes[13], guid_bytes[14], guid_bytes[15]);
                    // GUID_NULL or all-zero GUID means create a keyboard/mouse device (first available)
                    let is_null = guid_bytes.iter().all(|&b| b == 0);
                    let device_guid = if is_null {
                        // Use first available controller, or create a synthetic keyboard device
                        let devices = self.user32.enum_directinput_devices();
                        if let Some(first) = devices.first() {
                            first.guid.clone()
                        } else {
                            // No controllers registered; create a synthetic keyboard GUID
                            self.user32.create_directinput_device("SYSTEM_KEYBOARD")
                                .unwrap_or_else(|_| "SYSTEM_KEYBOARD".to_string())
                        }
                    } else {
                        guid_str.clone()
                    };
                    // Check if the device exists
                    let device_result = self.user32.create_directinput_device(&device_guid);
                    match device_result {
                        Ok(_guid) => {
                            let device_object = self.alloc_directinput8_device_object(memory, device_guid.clone())?;
                            write_u64(memory, out_ptr, device_object);
                            state.set(Register::Rax, 0);
                        }
                        Err(e) => {
                            state.set(Register::Rax, 0x80070057u64 as u64); // E_INVALIDARG
                        }
                    }
