                let filled = if self.device_contexts.contains_key(&hdc) && rect_ptr != 0 && brush != 0 {
                    let left = read_i32_from_memory(memory, rect_ptr)?;
                    let top = read_i32_from_memory(memory, rect_ptr + 4)?;
                    let right = read_i32_from_memory(memory, rect_ptr + 8)?;
                    let bottom = read_i32_from_memory(memory, rect_ptr + 12)?;
                    let color = brush_to_bgra(brush, &self.gdi_brushes);
                    // Draw top edge
                    if left < right && top < bottom {
                        self.fill_hdc_rect(hdc, preview_rect_from_bounds(left, top, right, top + 1), color);
                        // Draw bottom edge
                        self.fill_hdc_rect(hdc, preview_rect_from_bounds(left, bottom - 1, right, bottom), color);
                        // Draw left edge
                        self.fill_hdc_rect(hdc, preview_rect_from_bounds(left, top + 1, left + 1, bottom - 1), color);
                        // Draw right edge
                        self.fill_hdc_rect(hdc, preview_rect_from_bounds(right - 1, top + 1, right, bottom - 1), color);
                    }
                    true
                } else {
                    false
                };
