                            let addr = block_ptr + fixed_offset as u64;
                            write_guest_pointer(memory, buffer_ptr, addr, self.guest_arch)?;
                            write_u32(memory, len_ptr, 52); // sizeof(VS_FIXEDFILEINFO)
