                    let duration = std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default();
                    let days_since_epoch = duration.as_secs() / 86400;
                    // Calculate year/month/day from days since 1970-01-01
                    let (year, month, day) = {
                        let mut y = 1970;
                        let mut remaining = days_since_epoch;
                        loop {
                            let days_in_year = if (y % 4 == 0 && y % 100 != 0) || y % 400 == 0 { 366 } else { 365 };
                            if remaining < days_in_year { break; }
                            remaining -= days_in_year;
                            y += 1;
                        }
                        let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
                        let month_days: [u64; 12] = if leap { [31,29,31,30,31,30,31,31,30,31,30,31] } else { [31,28,31,30,31,30,31,31,30,31,30,31] };
                        let mut m = 0;
                        for &md in &month_days {
                            if remaining < md { break; }
                            remaining -= md;
                            m += 1;
                        }
                        (y as u16, (m + 1) as u16, (remaining + 1) as u16)
                    };
                    let secs_of_day = duration.as_secs() % 86400;
                    let hour = (secs_of_day / 3600) as u16;
                    let minute = ((secs_of_day % 3600) / 60) as u16;
                    let second = (secs_of_day % 60) as u16;
                    let millis = (duration.as_millis() % 1000) as u16;
