/// Returns `true` if the runtime has a concrete dispatch handler for the given
/// (dll, symbol) import.  Used by integration tests to produce coverage reports.
pub fn is_import_supported(dll: &str, symbol: &ImportSymbol) -> bool {
    let import = ResolvedImport {
        requested_module: dll.to_string(),
        resolved_module: dll.to_string(),
        symbol: symbol.clone(),
        iat_rva: 0,
        export: synthetic_export_symbol(symbol),
    };
    let thunk = HostThunk::from_import(&import);
    !matches!(thunk, HostThunk::Unsupported { .. })
}

fn resolve_imports_for_runtime(image: &pe::ParsedPe, resolver: &ApiSetResolver) -> Vec<ResolvedImport> {
    image
        .imports
        .iter()
        .chain(image.delay_imports.iter())
        .flat_map(|descriptor| {
            let resolved_module = resolver.resolve(&descriptor.dll_name);
            descriptor.imports.iter().map(move |thunk| ResolvedImport {
                requested_module: descriptor.dll_name.clone(),
                resolved_module: resolved_module.clone(),
                symbol: thunk.symbol.clone(),
                iat_rva: thunk.iat_rva,
                export: synthetic_export_symbol(&thunk.symbol),
            })
        })
        .collect()
}

fn synthetic_export_symbol(symbol: &ImportSymbol) -> ExportSymbol {
    match symbol {
        ImportSymbol::ByName { name, .. } => ExportSymbol {
            ordinal: 0,
            name: Some(name.clone()),
            target: ExportTarget::Rva(0),
        },
        ImportSymbol::ByOrdinal { ordinal } => ExportSymbol {
            ordinal: *ordinal as u32,
            name: None,
            target: ExportTarget::Rva(0),
        },
    }
}

fn decode_current_instruction(
    engine: &CpuExecutionEngine,
    memory: &MemoryImage,
    rip: u64,
) -> AppResult<DecodedInstruction> {
    let mut bytes = [0_u8; 15];
    memory.read_into_slice(rip, &mut bytes)?;
    for len in (1..=bytes.len()).rev() {
        if let Ok(decoded) = engine.decode_block(&bytes[..len], rip) {
            if decoded.len() == 1 && decoded[0].size == len {
                return Ok(decoded.into_iter().next().expect("decoded instruction"));
            }
        }
    }
    let window = bytes
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<Vec<_>>()
        .join(" ");
    Err(AppError::new(
        ReasonCode::RcUnimplInsn,
        format!("failed to decode guest instruction at {rip:#x}: {window}"),
    ))
}

fn decode_current_instruction_cached(
    engine: &CpuExecutionEngine,
    memory: &MemoryImage,
    instruction_cache: &mut U64Map<CachedInstructionEntry>,
    instruction_cache_lru: &mut VecDeque<(u64, u64)>,
    instruction_cache_generation: &mut u64,
    instruction_cache_limit: usize,
    rip: u64,
) -> AppResult<Arc<CachedInstruction>> {
    if let Some(cached) = instruction_cache.get_mut(&rip) {
        if read_window_matches(memory, rip, cached.cached.bytes.as_slice())? {
            *instruction_cache_generation = instruction_cache_generation.saturating_add(1);
            cached.generation = *instruction_cache_generation;
            instruction_cache_lru.push_back((rip, cached.generation));
            return Ok(Arc::clone(&cached.cached));
        }
    }

    let decoded = decode_current_instruction(engine, memory, rip)?;
    let mut bytes = vec![0; decoded.size];
    memory.read_into_slice(rip, &mut bytes)?;
    *instruction_cache_generation = instruction_cache_generation.saturating_add(1);
    let cached = Arc::new(CachedInstruction {
        bytes,
        decoded,
    });
    let generation = *instruction_cache_generation;

    instruction_cache.insert(
        rip,
        CachedInstructionEntry {
            cached: Arc::clone(&cached),
            generation,
        },
    );
    instruction_cache_lru.push_back((rip, generation));
    trim_instruction_cache(instruction_cache, instruction_cache_lru, instruction_cache_limit);
    Ok(cached)
}

fn decode_basic_block_cached(
    engine: &mut CpuExecutionEngine,
    memory: &MemoryImage,
    instruction_cache: &mut U64Map<CachedInstructionEntry>,
    instruction_cache_lru: &mut VecDeque<(u64, u64)>,
    instruction_cache_generation: &mut u64,
    instruction_cache_limit: usize,
    basic_block_cache: &mut U64Map<CachedBlockEntry>,
    basic_block_cache_lru: &mut VecDeque<(u64, u64)>,
    basic_block_cache_generation: &mut u64,
    basic_block_cache_limit: usize,
    rip: u64,
    jit_runtime: Option<&mut crate::jit::JitRuntime>,
) -> AppResult<Arc<CachedBlock>> {
    if let Some(cached) = basic_block_cache.get_mut(&rip) {
        if read_window_matches(memory, rip, cached.cached.bytes.as_slice())? {
            *basic_block_cache_generation = basic_block_cache_generation.saturating_add(1);
            cached.generation = *basic_block_cache_generation;
            basic_block_cache_lru.push_back((rip, cached.generation));
            return Ok(Arc::clone(&cached.cached));
        }
        // Cache miss — memory content changed. Invalidate any stale JIT
        // compiled block and unchain incoming jumps so we don't execute
        // the old code.
        if let Some(jit) = jit_runtime {
            if jit.is_compiled(rip) {
                let _ = jit.unchain_target(rip);
            }
        }
    }

    let mut current_rip = rip;
    let mut bytes = Vec::new();
    let mut end_rip = rip;
    for _inst_idx in 0..BASIC_BLOCK_MAX_INSTRUCTIONS {
        let cached_instruction = decode_current_instruction_cached(
            engine,
            memory,
            instruction_cache,
            instruction_cache_lru,
            instruction_cache_generation,
            instruction_cache_limit,
            current_rip,
        )?;
        let decoded = &cached_instruction.decoded;
        let decoded_bytes = cached_instruction.bytes.as_slice();
        if !bytes.is_empty() && bytes.len() + decoded_bytes.len() > BASIC_BLOCK_MAX_BYTES {
            break;
        }
        end_rip = current_rip + decoded.size as u64;
        bytes.extend_from_slice(decoded_bytes);
        if instruction_controls_rip(decoded.opcode) || decoded.opcode == DecodedOpcode::Ret {
            break;
        }
        current_rip = end_rip;
    }

    if bytes.is_empty() {
        return Err(AppError::new(
            ReasonCode::RcUnimplInsn,
            format!("failed to build basic block at {rip:#x}"),
        ));
    }

    let translated = engine.translate_block(&bytes, rip)?;
    *basic_block_cache_generation = basic_block_cache_generation.saturating_add(1);
    let cached = Arc::new(CachedBlock {
        bytes,
        translated,
        start_rip: rip,
        end_rip,
    });
    let generation = *basic_block_cache_generation;
    basic_block_cache.insert(
        rip,
        CachedBlockEntry {
            cached: Arc::clone(&cached),
            generation,
        },
    );
    basic_block_cache_lru.push_back((rip, generation));
    trim_basic_block_cache(
        basic_block_cache,
        basic_block_cache_lru,
        basic_block_cache_limit,
    );
    Ok(cached)
}

fn trim_instruction_cache(
    instruction_cache: &mut U64Map<CachedInstructionEntry>,
    instruction_cache_lru: &mut VecDeque<(u64, u64)>,
    instruction_cache_limit: usize,
) {
    while instruction_cache.len() > instruction_cache_limit {
        let Some((rip, generation)) = instruction_cache_lru.pop_front() else {
            break;
        };
        let remove = instruction_cache
            .get(&rip)
            .map(|cached| cached.generation == generation)
            .unwrap_or(false);
        if remove {
            instruction_cache.remove(&rip);
        }
    }
}

fn trim_basic_block_cache(
    basic_block_cache: &mut U64Map<CachedBlockEntry>,
    basic_block_cache_lru: &mut VecDeque<(u64, u64)>,
    basic_block_cache_limit: usize,
) {
    while basic_block_cache.len() > basic_block_cache_limit {
        let Some((rip, generation)) = basic_block_cache_lru.pop_front() else {
            break;
        };
        let remove = basic_block_cache
            .get(&rip)
            .map(|cached| cached.generation == generation)
            .unwrap_or(false);
        if remove {
            basic_block_cache.remove(&rip);
        }
    }
}

fn annotate_guest_fault(error: AppError, memory: &MemoryImage, state: &CpuState) -> AppError {
    let rip = state.rip;
    let window = read_window(memory, rip, 15)
        .map(|bytes| {
            bytes
                .iter()
                .map(|byte| format!("{byte:02x}"))
                .collect::<Vec<_>>()
                .join(" ")
        })
        .unwrap_or_else(|_| "<unavailable>".to_string());
    let registers = format!(
        "rax={:#x} rbx={:#x} rcx={:#x} rdx={:#x} rsi={:#x} rdi={:#x} rsp={:#x} rbp={:#x}",
        state.get(Register::Rax),
        state.get(Register::Rbx),
        state.get(Register::Rcx),
        state.get(Register::Rdx),
        state.get(Register::Rsi),
        state.get(Register::Rdi),
        state.get(Register::Rsp),
        state.get(Register::Rbp),
    );
    let mut wrapped = AppError::new(
        error.code,
        format!("{} while executing guest instruction at {rip:#x}: {window} | {registers}", error.message),
    );
    if let Ok(bytes) = read_window(memory, rip, 64) {
        let raw_block = bytes
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<Vec<_>>()
            .join(" ");
        match crate::cpu::decode_block(&bytes, rip, state.arch) {
            Ok(decoded) => {
                let summary = decoded
                    .iter()
                    .take(8)
                    .map(|instruction| {
                        format!(
                            "{:#x}:{:?} {:?}",
                            instruction.address,
                            instruction.opcode,
                            instruction.operands,
                        )
                    })
                    .collect::<Vec<_>>()
                    .join(" || ");
                if !summary.is_empty() {
                    wrapped = wrapped.with_hint(format!("fault-block {summary}"));
                }
            }
            Err(decode_error) => {
                wrapped = wrapped.with_hint(format!(
                    "fault-block decode-failed={} bytes={raw_block}",
                    decode_error.message,
                ));
            }
        }
    }
    if let Ok(bytes) = read_window(memory, rip, 16) {
        if bytes.starts_with(&[0xc5, 0xf5, 0x74, 0x01, 0xc5, 0xfd, 0xd7, 0xc0]) {
            let caller = read_guest_u32(memory, state.get(Register::Rbp) + 4)
                .ok()
                .map(u64::from);
            let arg0 = read_guest_u32(memory, state.get(Register::Rbp) + 8)
                .ok()
                .map(u64::from)
                .unwrap_or(0);
            let arg1 = read_guest_u32(memory, state.get(Register::Rbp) + 12)
                .ok()
                .map(u64::from)
                .unwrap_or(0);
            let mut mapped = Vec::new();
            let mut first_unmapped = None;
            if arg0 != 0 {
                for offset in 0..64_u64 {
                    match memory.read_u8(arg0 + offset) {
                        Ok(byte) => mapped.push(byte),
                        Err(_) => {
                            first_unmapped = Some(arg0 + offset);
                            break;
                        }
                    }
                }
            }
            let hex = mapped
                .iter()
                .map(|byte| format!("{byte:02x}"))
                .collect::<Vec<_>>()
                .join(" ");
            let ascii = mapped
                .iter()
                .map(|byte| {
                    if byte.is_ascii_graphic() || *byte == b' ' {
                        char::from(*byte)
                    } else {
                        '.'
                    }
                })
                .collect::<String>();
            wrapped = wrapped.with_hint(format!(
                "steam-avx-strscan caller={} arg0={arg0:#x} arg1={arg1:#x} mapped_len={} first_unmapped={} hex=[{hex}] ascii={ascii}",
                caller
                    .map(|value| format!("{value:#x}"))
                    .unwrap_or_else(|| "<unavailable>".to_string()),
                mapped.len(),
                first_unmapped
                    .map(|value| format!("{value:#x}"))
                    .unwrap_or_else(|| "<none>".to_string()),
            ));
        }
    }
    if rip == 0x401390 {
        let state_table = read_guest_u32(memory, 0x42a250).ok().map(u64::from);
        let record_base = read_guest_u32(memory, 0x42a270).ok().map(u64::from);
        let slot_values = state_table
            .map(|base| {
                (0..8)
                    .map(|index| {
                        let value = read_guest_u32(memory, base + 0x6c + index * 4)
                            .ok()
                            .map(u64::from)
                            .unwrap_or(0);
                        format!("{index}:{value:#x}")
                    })
                    .collect::<Vec<_>>()
                    .join(",")
            })
            .unwrap_or_else(|| "<unavailable>".to_string());
        let class_block = [0x4291e0_u64, 0x4291e4, 0x4291f0, 0x4291f4, 0x429204]
            .into_iter()
            .map(|address| {
                let value = read_guest_u32(memory, address)
                    .ok()
                    .map(u64::from)
                    .unwrap_or(0);
                format!("{address:#x}={value:#x}")
            })
            .collect::<Vec<_>>()
            .join(",");
        let stack_probe = [state.get(Register::Rsp) + 4, state.get(Register::Rsp) + 8, state.get(Register::Rsp) + 12]
            .into_iter()
            .map(|address| {
                let value = read_guest_u32(memory, address)
                    .ok()
                    .map(u64::from)
                    .unwrap_or(0);
                format!("{address:#x}={value:#x}")
            })
            .collect::<Vec<_>>()
            .join(",");
        let current_index = read_guest_u32(memory, state.get(Register::Rsp) + 8)
            .ok()
            .map(u64::from);
        let current_record = current_index
            .zip(record_base)
            .map(|(index, base)| {
                let record_address = base + index * 0x1c;
                let fields = (0..7)
                    .map(|slot| {
                        let value = read_guest_u32(memory, record_address + slot * 4)
                            .ok()
                            .map(u64::from)
                            .unwrap_or(0);
                        format!("{slot}:{value:#x}")
                    })
                    .collect::<Vec<_>>()
                    .join(",");
                format!("addr={record_address:#x} fields=[{fields}]")
            })
            .unwrap_or_else(|| "<unavailable>".to_string());
        wrapped = wrapped.with_hint(format!(
            "steam-401390 probe state_table={} record_base={} slot_6c=[{}] class_block=[{}] stack=[{}] current_record={}",
            state_table
                .map(|value| format!("{value:#x}"))
                .unwrap_or_else(|| "<unavailable>".to_string()),
            record_base
                .map(|value| format!("{value:#x}"))
                .unwrap_or_else(|| "<unavailable>".to_string()),
            slot_values,
            class_block,
            stack_probe,
            current_record,
        ));
    }
    if let Some(fault_address) = guest_access_violation_address(&error) {
        if fault_address < 0x1000 {
            let frame_probe = [
                state.get(Register::Rbp) + 4,
                state.get(Register::Rbp) + 8,
                state.get(Register::Rbp) + 12,
                state.get(Register::Rbp) + 16,
            ]
            .into_iter()
            .map(|address| {
                let value = read_guest_u32(memory, address)
                    .ok()
                    .map(u64::from)
                    .unwrap_or(0);
                format!("{address:#x}={value:#x}")
            })
            .collect::<Vec<_>>()
            .join(",");
            let parent_ebp = read_guest_u32(memory, state.get(Register::Rbp))
                .ok()
                .map(u64::from)
                .unwrap_or(0);
            let parent_arg1 = if parent_ebp != 0 {
                read_guest_u32(memory, parent_ebp + 12).ok().map(u64::from)
            } else {
                None
            };
            let parent_arg2 = if parent_ebp != 0 {
                read_guest_u32(memory, parent_ebp + 16).ok().map(u64::from)
            } else {
                None
            };
            let parent_frame_probe = if parent_ebp != 0 {
                [parent_ebp + 4, parent_ebp + 8, parent_ebp + 12, parent_ebp + 16]
                    .into_iter()
                    .map(|address| {
                        let value = read_guest_u32(memory, address)
                            .ok()
                            .map(u64::from)
                            .unwrap_or(0);
                        format!("{address:#x}={value:#x}")
                    })
                    .collect::<Vec<_>>()
                    .join(",")
            } else {
                "<unavailable>".to_string()
            };
            let parent_arg1_probe = match (parent_arg1, parent_arg2) {
                (Some(address), Some(length)) if address != 0 && length != 0 && length <= 64 => {
                    match read_window(memory, address, length as usize) {
                        Ok(bytes) => {
                            let hex = bytes
                                .iter()
                                .map(|byte| format!("{byte:02x}"))
                                .collect::<Vec<_>>()
                                .join(" ");
                            let ascii = bytes
                                .iter()
                                .map(|byte| {
                                    if byte.is_ascii_graphic() || *byte == b' ' {
                                        char::from(*byte)
                                    } else {
                                        '.'
                                    }
                                })
                                .collect::<String>();
                            let first_entry_probe = if bytes.len() >= 4 {
                                let first_entry = u64::from(u32::from_le_bytes(bytes[0..4].try_into().unwrap()));
                                if first_entry != 0 {
                                    match read_window(memory, first_entry, 64) {
                                        Ok(pointed_bytes) => {
                                            let end = pointed_bytes
                                                .iter()
                                                .position(|byte| *byte == 0)
                                                .unwrap_or(pointed_bytes.len());
                                            let pointed_ascii = pointed_bytes[..end]
                                                .iter()
                                                .map(|byte| {
                                                    if byte.is_ascii_graphic() || *byte == b' ' {
                                                        char::from(*byte)
                                                    } else {
                                                        '.'
                                                    }
                                                })
                                                .collect::<String>();
                                            format!(" first_entry={first_entry:#x} first_ascii={pointed_ascii}")
                                        }
                                        Err(_) => format!(" first_entry={first_entry:#x} unreadable"),
                                    }
                                } else {
                                    String::new()
                                }
                            } else {
                                String::new()
                            };
                            format!("addr={address:#x} len={length:#x} hex=[{hex}] ascii={ascii}{first_entry_probe}")
                        }
                        Err(_) => format!("addr={address:#x} len={length:#x} unreadable"),
                    }
                }
                _ => "<unavailable>".to_string(),
            };
            wrapped = wrapped.with_hint(format!(
                "low-fault probe fault={fault_address:#x} rbx={:#x} frame=[{}] parent_ebp={parent_ebp:#x} parent_frame=[{}] parent_arg1={parent_arg1_probe}",
                state.get(Register::Rbx),
                frame_probe,
                parent_frame_probe,
            ));
        }
    }
    for hint in error.reproduction_hints {
        wrapped = wrapped.with_hint(hint);
    }
    wrapped
}

fn guest_access_violation_address(error: &AppError) -> Option<u64> {
    if error.code != ReasonCode::RcUnimplInsn {
        return None;
    }
    let encoded = error.message.strip_prefix("unmapped guest memory at ")?;
    let hex = encoded.split_whitespace().next()?.strip_prefix("0x")?;
    u64::from_str_radix(hex, 16).ok()
}

fn pack_x86_eflags(state: &CpuState) -> u32 {
    let mut value = 0x2_u32 | ((state.eflags_extra & !0x8d7_u64) as u32);
    if state.flags.cf {
        value |= 1 << 0;
    }
    if state.flags.pf {
        value |= 1 << 2;
    }
    if state.flags.af {
        value |= 1 << 4;
    }
    if state.flags.zf {
        value |= 1 << 6;
    }
    if state.flags.sf {
        value |= 1 << 7;
    }
    if state.flags.of {
        value |= 1 << 11;
    }
    value
}

fn unpack_x86_eflags(state: &mut CpuState, value: u32) {
    state.flags.cf = value & (1 << 0) != 0;
    state.flags.pf = value & (1 << 2) != 0;
    state.flags.af = value & (1 << 4) != 0;
    state.flags.zf = value & (1 << 6) != 0;
    state.flags.sf = value & (1 << 7) != 0;
    state.flags.of = value & (1 << 11) != 0;
    state.eflags_extra = u64::from(value & !0x8d7_u32);
}

fn write_x86_exception_record(memory: &mut MemoryImage, base: u64, fault_address: u64, exception_rip: u32) {
    write_u32(memory, base, crate::cpu::EXCEPTION_ACCESS_VIOLATION);
    write_u32(memory, base + 4, 0);
    write_u32(memory, base + 8, 0);
    write_u32(memory, base + 12, exception_rip);
    write_u32(memory, base + 16, 2);
    write_u32(memory, base + 20, 0);
    write_u32(memory, base + 24, fault_address as u32);
}

fn write_x86_context(memory: &mut MemoryImage, base: u64, state: &CpuState) {
    write_u32(memory, base, X86_CONTEXT_FLAGS_FULL);
    write_u32(memory, base + X86_CONTEXT_OFFSET_SEG_GS, 0);
    write_u32(memory, base + X86_CONTEXT_OFFSET_SEG_FS, 0);
    write_u32(memory, base + X86_CONTEXT_OFFSET_SEG_ES, 0x23);
    write_u32(memory, base + X86_CONTEXT_OFFSET_SEG_DS, 0x23);
    write_u32(memory, base + X86_CONTEXT_OFFSET_EDI, state.get(Register::Rdi) as u32);
    write_u32(memory, base + X86_CONTEXT_OFFSET_ESI, state.get(Register::Rsi) as u32);
    write_u32(memory, base + X86_CONTEXT_OFFSET_EBX, state.get(Register::Rbx) as u32);
    write_u32(memory, base + X86_CONTEXT_OFFSET_EDX, state.get(Register::Rdx) as u32);
    write_u32(memory, base + X86_CONTEXT_OFFSET_ECX, state.get(Register::Rcx) as u32);
    write_u32(memory, base + X86_CONTEXT_OFFSET_EAX, state.get(Register::Rax) as u32);
    write_u32(memory, base + X86_CONTEXT_OFFSET_EBP, state.get(Register::Rbp) as u32);
    write_u32(memory, base + X86_CONTEXT_OFFSET_EIP, state.rip as u32);
    write_u32(memory, base + X86_CONTEXT_OFFSET_SEG_CS, 0x1b);
    write_u32(memory, base + X86_CONTEXT_OFFSET_EFLAGS, pack_x86_eflags(state));
    write_u32(memory, base + X86_CONTEXT_OFFSET_ESP, state.get(Register::Rsp) as u32);
    write_u32(memory, base + X86_CONTEXT_OFFSET_SEG_SS, 0x23);
}

fn read_x86_context(memory: &MemoryImage, base: u64, state: &mut CpuState) -> AppResult<()> {
    state.set(Register::Rdi, u64::from(read_guest_u32(memory, base + X86_CONTEXT_OFFSET_EDI)?));
    state.set(Register::Rsi, u64::from(read_guest_u32(memory, base + X86_CONTEXT_OFFSET_ESI)?));
    state.set(Register::Rbx, u64::from(read_guest_u32(memory, base + X86_CONTEXT_OFFSET_EBX)?));
    state.set(Register::Rdx, u64::from(read_guest_u32(memory, base + X86_CONTEXT_OFFSET_EDX)?));
    state.set(Register::Rcx, u64::from(read_guest_u32(memory, base + X86_CONTEXT_OFFSET_ECX)?));
    state.set(Register::Rax, u64::from(read_guest_u32(memory, base + X86_CONTEXT_OFFSET_EAX)?));
    state.set(Register::Rbp, u64::from(read_guest_u32(memory, base + X86_CONTEXT_OFFSET_EBP)?));
    state.rip = u64::from(read_guest_u32(memory, base + X86_CONTEXT_OFFSET_EIP)?);
    state.set(Register::Rsp, u64::from(read_guest_u32(memory, base + X86_CONTEXT_OFFSET_ESP)?));
    unpack_x86_eflags(state, read_guest_u32(memory, base + X86_CONTEXT_OFFSET_EFLAGS)?);
    Ok(())
}

fn instruction_controls_rip(opcode: DecodedOpcode) -> bool {
    matches!(
        opcode,
        DecodedOpcode::CallRel
            | DecodedOpcode::CallMemory
            | DecodedOpcode::CallRegister
            | DecodedOpcode::Jcc
            | DecodedOpcode::JmpRel
            | DecodedOpcode::JmpRegister
            | DecodedOpcode::JmpMemory
    )
}

fn advance_runtime_steps(
    runtime: &mut PeHostRuntime,
    steps: &mut u64,
    instruction_budget: u64,
    consumed_instructions: u64,
    memory: &MemoryImage,
    state: &CpuState,
    test_id: &str,
) -> AppResult<()> {
    let next_steps = steps.saturating_add(consumed_instructions);
    if state.arch == GuestArch::X86 && runtime.enable_steam_tracing {
        let rip = state.rip;
        let rva = rip.saturating_sub(runtime.mapped_image_base);
        if runtime.steam_owner_allocator_probe_count < 16
            && (0x000a_bfd7..=0x000a_c04b).contains(&rva)
        {
            let counter_str = probe_read_guest_u32(memory, runtime.mapped_image_base + 0x003c_873c)
                .map(|value| format!("{value:#x}"))
                .unwrap_or_else(|| "<unavailable>".to_string());
            runtime.push_trace(
                "process",
                "SteamOwnerAllocatorStep",
                BTreeMap::from([
                    ("rip_rva".to_string(), json!(format!("{rva:#x}"))),
                    ("counter".to_string(), json!(counter_str)),
                    ("eax".to_string(), json!(format!("{:#x}", state.get(Register::Rax)))),
                    ("ecx".to_string(), json!(format!("{:#x}", state.get(Register::Rcx)))),
                    ("esi".to_string(), json!(format!("{:#x}", state.get(Register::Rsi)))),
                    ("ebp".to_string(), json!(format!("{:#x}", state.get(Register::Rbp)))),
                    ("esp".to_string(), json!(format!("{:#x}", state.get(Register::Rsp)))),
                ]),
                json!(state.get(Register::Rax)),
            );
            runtime.steam_owner_allocator_probe_count += 1;
        }
        if runtime.steam_4ae970_probe_count < 16
            && (0x000a_e970..=0x000a_ea10).contains(&rva)
        {
            let counter_str = probe_read_guest_u32(memory, runtime.mapped_image_base + 0x003c_873c)
                .map(|value| format!("{value:#x}"))
                .unwrap_or_else(|| "<unavailable>".to_string());
            runtime.push_trace(
                "process",
                "SteamHashStep",
                BTreeMap::from([
                    ("rip_rva".to_string(), json!(format!("{rva:#x}"))),
                    ("owner_counter".to_string(), json!(counter_str)),
                    ("edi".to_string(), json!(format!("{:#x}", state.get(Register::Rdi)))),
                    ("ebx".to_string(), json!(format!("{:#x}", state.get(Register::Rbx)))),
                    ("ecx".to_string(), json!(format!("{:#x}", state.get(Register::Rcx)))),
                    ("ebp".to_string(), json!(format!("{:#x}", state.get(Register::Rbp)))),
                    ("esp".to_string(), json!(format!("{:#x}", state.get(Register::Rsp)))),
                ]),
                json!(state.get(Register::Rax)),
            );
            runtime.steam_4ae970_probe_count += 1;
        }
    }
    if next_steps > instruction_budget {
        let rip = state.rip;
        let window = read_window(memory, rip, 15)
            .map(|bytes| {
                bytes
                    .iter()
                    .map(|byte| format!("{byte:02x}"))
                    .collect::<Vec<_>>()
                    .join(" ")
            })
            .unwrap_or_else(|_| "<unavailable>".to_string());
        let register_context = match state.arch {
            GuestArch::X64 => format!(
                " rax={:#x} rbx={:#x} rcx={:#x} rdx={:#x} rsi={:#x} rdi={:#x}",
                state.get(Register::Rax),
                state.get(Register::Rbx),
                state.get(Register::Rcx),
                state.get(Register::Rdx),
                state.get(Register::Rsi),
                state.get(Register::Rdi),
            ),
            GuestArch::X86 => format!(
                " eax={:#x} ebx={:#x} ecx={:#x} edx={:#x} esi={:#x} edi={:#x} ebp={:#x} esp={:#x}",
                state.get(Register::Rax),
                state.get(Register::Rbx),
                state.get(Register::Rcx),
                state.get(Register::Rdx),
                state.get(Register::Rsi),
                state.get(Register::Rdi),
                state.get(Register::Rbp),
                state.get(Register::Rsp),
            ),
        };
        let steam_hot_rva = rip.saturating_sub(runtime.mapped_image_base);
        let steam_hot_context = if runtime.enable_steam_tracing
            && state.arch == GuestArch::X86
            && ((0x000a_e970..=0x000a_ea10).contains(&steam_hot_rva) || rip == 0x190a_e9dc)
        {
            format!(
                " steam_frame_key={} steam_owner_counter={} steam_stack_return={}",
                probe_read_guest_u32(memory, state.get(Register::Rbp) + 8)
                    .map(|value| format!("{value:#x}"))
                    .unwrap_or_else(|| "<unavailable>".to_string()),
                probe_read_guest_u32(memory, runtime.mapped_image_base + 0x003c_873c)
                    .map(|value| format!("{value:#x}"))
                    .unwrap_or_else(|| "<unavailable>".to_string()),
                probe_read_guest_u32(memory, state.get(Register::Rsp))
                    .map(|value| format!("{:#x}", u64::from(value).saturating_sub(runtime.mapped_image_base)))
                    .unwrap_or_else(|| "<unavailable>".to_string()),
            )
        } else {
            String::new()
        };
        return Err(AppError::new(
            ReasonCode::RcUnimplInsn,
            format!(
                "PE runtime exceeded the instruction budget for {test_id} at {rip:#x}: {window} steps={next_steps} budget={instruction_budget}{register_context}{steam_hot_context}"
            ),
        ));
    }

    let previous_poll_bucket = *steps >> 8;
    let next_poll_bucket = next_steps >> 8;
    *steps = next_steps;
    for _ in previous_poll_bucket..next_poll_bucket {
        runtime.poll_live_input()?;
    }
    Ok(())
}

fn pe_runtime_instruction_budget(env: &BTreeMap<String, String>, live_mode: bool) -> AppResult<u64> {
    match env
        .get(PE_RUNTIME_BUDGET_ENV)
        .cloned()
        .or_else(|| std::env::var(PE_RUNTIME_BUDGET_ENV).ok())
    {
        None => Ok(if live_mode {
            u64::MAX
        } else {
            PE_RUNTIME_INSTRUCTION_BUDGET
        }),
        Some(raw) => raw.parse::<u64>().map_err(|error| {
            AppError::new(
                ReasonCode::RcCliInvalid,
                format!("invalid {PE_RUNTIME_BUDGET_ENV} value {raw:?}"),
            )
            .with_hint(error.to_string())
        }),
    }
}

fn registry_view_from_sam_desired(sam_desired: u32, guest_arch: GuestArch) -> RegistryView {
    if sam_desired & KEY_WOW64_64KEY != 0 {
        RegistryView::Native64
    } else if sam_desired & KEY_WOW64_32KEY != 0 {
        RegistryView::Wow6432
    } else if guest_arch == GuestArch::X86 {
        RegistryView::Wow6432
    } else {
        RegistryView::Native
    }
}

fn resolve_registry_root_key(
    win32: &Win32Subsystem,
    hkey: u32,
    requested_view: RegistryView,
) -> AppResult<(String, String, RegistryView)> {
    match hkey {
        HKEY_CLASSES_ROOT => Ok(("HKCR".to_string(), String::new(), requested_view)),
        HKEY_CURRENT_USER => Ok(("HKCU".to_string(), String::new(), requested_view)),
        HKEY_LOCAL_MACHINE => Ok(("HKLM".to_string(), String::new(), requested_view)),
        HKEY_USERS => Ok(("HKCU".to_string(), String::new(), requested_view)),
        HKEY_CURRENT_CONFIG => Ok((
            "HKLM".to_string(),
            "System\\CurrentControlSet\\Hardware Profiles\\Current".to_string(),
            requested_view,
        )),
        _ => {
            let key = win32.key_state(hkey)?;
            Ok((key.hive, key.key, key.view))
        }
    }
}

fn join_registry_subkey(base: &str, suffix: &str) -> String {
    if base.is_empty() {
        suffix.trim_matches('\\').to_string()
    } else if suffix.is_empty() {
        base.trim_matches('\\').to_string()
    } else {
        format!("{}\\{}", base.trim_matches('\\'), suffix.trim_matches('\\'))
    }
}

fn normalize_registry_runtime_key(hive: &str, key: &str) -> String {
    if hive == "HKCU" {
        key.strip_prefix(".DEFAULT\\")
            .or_else(|| key.strip_prefix(".Default\\"))
            .unwrap_or(key)
            .trim_matches('\\')
            .to_string()
    } else {
        key.trim_matches('\\').to_string()
    }
}

fn registry_value_type_to_win32(value_type: &str) -> AppResult<u32> {
    match value_type.to_ascii_uppercase().as_str() {
        "REG_SZ" => Ok(REG_SZ),
        "REG_EXPAND_SZ" => Ok(REG_EXPAND_SZ),
        "REG_BINARY" => Ok(REG_BINARY),
        "REG_DWORD" => Ok(REG_DWORD),
        "REG_MULTI_SZ" => Ok(REG_MULTI_SZ),
        "REG_QWORD" => Ok(REG_QWORD),
        other => Err(AppError::new(
            ReasonCode::RcCliInvalid,
            format!("unsupported registry value type {other}"),
        )),
    }
}

fn decode_registry_value_data(
    memory: &MemoryImage,
    data_ptr: u64,
    data_len: u32,
    value_type: u32,
) -> AppResult<(String, Value)> {
    let bytes = if data_ptr == 0 || data_len == 0 {
        Vec::new()
    } else {
        memory.read_bytes(data_ptr, data_len as usize)?
    };
    match value_type {
        REG_SZ | REG_EXPAND_SZ => {
            let units = bytes
                .chunks_exact(2)
                .map(|chunk| u16::from_le_bytes([chunk[0], chunk[1]]))
                .collect::<Vec<_>>();
            let trimmed = units
                .iter()
                .copied()
                .take_while(|unit| *unit != 0)
                .collect::<Vec<_>>();
            Ok((
                if value_type == REG_SZ {
                    "REG_SZ".to_string()
                } else {
                    "REG_EXPAND_SZ".to_string()
                },
                json!(String::from_utf16_lossy(&trimmed)),
            ))
        }
        REG_DWORD => {
            if bytes.len() < 4 {
                return Err(AppError::new(
                    ReasonCode::RcCliInvalid,
                    "REG_DWORD data is shorter than 4 bytes",
                ));
            }
            Ok(("REG_DWORD".to_string(), json!(u32::from_le_bytes(bytes[..4].try_into().expect("dword")))))
        }
        REG_QWORD => {
            if bytes.len() < 8 {
                return Err(AppError::new(
                    ReasonCode::RcCliInvalid,
                    "REG_QWORD data is shorter than 8 bytes",
                ));
            }
            Ok(("REG_QWORD".to_string(), json!(u64::from_le_bytes(bytes[..8].try_into().expect("qword")))))
        }
        REG_BINARY => Ok((
            "REG_BINARY".to_string(),
            json!(bytes.into_iter().map(u64::from).collect::<Vec<_>>()),
        )),
        REG_MULTI_SZ => {
            let units = bytes
                .chunks_exact(2)
                .map(|chunk| u16::from_le_bytes([chunk[0], chunk[1]]))
                .collect::<Vec<_>>();
            let mut items = Vec::new();
            let mut current = Vec::new();
            for unit in units {
                if unit == 0 {
                    if current.is_empty() {
                        break;
                    }
                    items.push(String::from_utf16_lossy(&current));
                    current.clear();
                } else {
                    current.push(unit);
                }
            }
            Ok(("REG_MULTI_SZ".to_string(), json!(items)))
        }
        other => Err(AppError::new(
            ReasonCode::RcCliInvalid,
            format!("unsupported registry value type code {other}"),
        )),
    }
}

fn encode_registry_value_data(value: &crate::ge::StoredRegistryValue) -> AppResult<Vec<u8>> {
    match value.value_type.to_ascii_uppercase().as_str() {
        "REG_SZ" | "REG_EXPAND_SZ" => {
            let text = value.data.as_str().ok_or_else(|| {
                AppError::new(
                    ReasonCode::RcCliInvalid,
                    format!("registry string value has non-string data: {:?}", value.data),
                )
            })?;
            Ok(text
                .encode_utf16()
                .chain(std::iter::once(0))
                .flat_map(|unit| unit.to_le_bytes())
                .collect())
        }
        "REG_DWORD" => {
            let number = value.data.as_u64().ok_or_else(|| {
                AppError::new(
                    ReasonCode::RcCliInvalid,
                    format!("registry dword value has non-numeric data: {:?}", value.data),
                )
            })?;
            Ok((number as u32).to_le_bytes().to_vec())
        }
        "REG_QWORD" => {
            let number = value.data.as_u64().ok_or_else(|| {
                AppError::new(
                    ReasonCode::RcCliInvalid,
                    format!("registry qword value has non-numeric data: {:?}", value.data),
                )
            })?;
            Ok(number.to_le_bytes().to_vec())
        }
        "REG_BINARY" => {
            let bytes = value.data.as_array().ok_or_else(|| {
                AppError::new(
                    ReasonCode::RcCliInvalid,
                    format!("registry binary value has non-array data: {:?}", value.data),
                )
            })?;
            bytes
                .iter()
                .map(|item| {
                    item.as_u64().map(|byte| byte as u8).ok_or_else(|| {
                        AppError::new(
                            ReasonCode::RcCliInvalid,
                            format!("registry binary value contains non-byte data: {item:?}"),
                        )
                    })
                })
                .collect()
        }
        "REG_MULTI_SZ" => {
            let items = value.data.as_array().ok_or_else(|| {
                AppError::new(
                    ReasonCode::RcCliInvalid,
                    format!("registry multi-string value has non-array data: {:?}", value.data),
                )
            })?;
            let mut encoded = Vec::new();
            for item in items {
                let text = item.as_str().ok_or_else(|| {
                    AppError::new(
                        ReasonCode::RcCliInvalid,
                        format!("registry multi-string value contains non-string data: {item:?}"),
                    )
                })?;
                encoded.extend(text.encode_utf16().flat_map(|unit| unit.to_le_bytes()));
                encoded.extend_from_slice(&0u16.to_le_bytes());
            }
            encoded.extend_from_slice(&0u16.to_le_bytes());
            Ok(encoded)
        }
        other => Err(AppError::new(
            ReasonCode::RcCliInvalid,
            format!("unsupported registry value type {other}"),
        )),
    }
}

fn decode_registry_value_data_ansi(
    memory: &MemoryImage,
    data_ptr: u64,
    data_len: u32,
    value_type: u32,
) -> AppResult<(String, Value)> {
    let bytes = if data_ptr == 0 || data_len == 0 {
        Vec::new()
    } else {
        memory.read_bytes(data_ptr, data_len as usize)?
    };
    match value_type {
        REG_SZ | REG_EXPAND_SZ => {
            let trimmed = bytes
                .iter()
                .copied()
                .take_while(|byte| *byte != 0)
                .map(char::from)
                .collect::<String>();
            Ok((
                if value_type == REG_SZ {
                    "REG_SZ".to_string()
                } else {
                    "REG_EXPAND_SZ".to_string()
                },
                json!(trimmed),
            ))
        }
        REG_DWORD | REG_QWORD | REG_BINARY => decode_registry_value_data(memory, data_ptr, data_len, value_type),
        REG_MULTI_SZ => {
            let mut items = Vec::new();
            let mut current = Vec::new();
            for byte in bytes {
                if byte == 0 {
                    if current.is_empty() {
                        break;
                    }
                    items.push(current.iter().copied().map(char::from).collect::<String>());
                    current.clear();
                } else {
                    current.push(byte);
                }
            }
            Ok(("REG_MULTI_SZ".to_string(), json!(items)))
        }
        other => Err(AppError::new(
            ReasonCode::RcCliInvalid,
            format!("unsupported registry value type code {other}"),
        )),
    }
}

fn encode_registry_value_data_ansi(value: &crate::ge::StoredRegistryValue) -> AppResult<Vec<u8>> {
    match value.value_type.to_ascii_uppercase().as_str() {
        "REG_SZ" | "REG_EXPAND_SZ" => {
            let text = value.data.as_str().ok_or_else(|| {
                AppError::new(
                    ReasonCode::RcCliInvalid,
                    format!("registry string value has non-string data: {:?}", value.data),
                )
            })?;
            let mut encoded = text
                .chars()
                .map(|ch| if ch.is_ascii() { ch as u8 } else { b'?' })
                .collect::<Vec<_>>();
            encoded.push(0);
            Ok(encoded)
        }
        "REG_DWORD" | "REG_QWORD" | "REG_BINARY" => encode_registry_value_data(value),
        "REG_MULTI_SZ" => {
            let items = value.data.as_array().ok_or_else(|| {
                AppError::new(
                    ReasonCode::RcCliInvalid,
                    format!("registry multi-string value has non-array data: {:?}", value.data),
                )
            })?;
            let mut encoded = Vec::new();
            for item in items {
                let text = item.as_str().ok_or_else(|| {
                    AppError::new(
                        ReasonCode::RcCliInvalid,
                        format!("registry multi-string value contains non-string data: {item:?}"),
                    )
                })?;
                encoded.extend(text.chars().map(|ch| if ch.is_ascii() { ch as u8 } else { b'?' }));
                encoded.push(0);
            }
            encoded.push(0);
            Ok(encoded)
        }
        other => Err(AppError::new(
            ReasonCode::RcCliInvalid,
            format!("unsupported registry value type {other}"),
        )),
    }
}

fn read_window(memory: &MemoryImage, address: u64, len: usize) -> AppResult<Vec<u8>> {
    let mut bytes = vec![0; len];
    memory.read_into_slice(address, &mut bytes)?;
    Ok(bytes)
}

fn read_window_matches(memory: &MemoryImage, address: u64, expected: &[u8]) -> AppResult<bool> {
    let mut offset = 0_usize;
    let mut scratch = [0_u8; 64];
    while offset < expected.len() {
        let chunk_len = (expected.len() - offset).min(scratch.len());
        let chunk = &mut scratch[..chunk_len];
        memory.read_into_slice(address + offset as u64, chunk)?;
        if chunk != &expected[offset..offset + chunk_len] {
            return Ok(false);
        }
        offset += chunk_len;
    }
    Ok(true)
}

fn probe_read_window(memory: &MemoryImage, address: u64, len: usize) -> Option<Vec<u8>> {
    if !memory.is_range_mapped(address, len) {
        return None;
    }
    read_window(memory, address, len).ok()
}

fn read_i32_from_memory(memory: &MemoryImage, address: u64) -> AppResult<i32> {
    let bytes = read_window(memory, address, 4)?;
    Ok(i32::from_le_bytes(bytes.try_into().expect("disp32")))
}

#[derive(Debug, Clone, Copy)]
struct GuestWindowClass {
    style: u32,
    wnd_proc: u64,
    cls_extra: i32,
    wnd_extra: i32,
    instance: u64,
    icon: u64,
    cursor: u64,
    background: u64,
    menu_name: u64,
    class_name_ptr: u64,
    icon_small: u64,
}

fn read_guest_window_class(
    memory: &MemoryImage,
    address: u64,
    guest_arch: GuestArch,
    extended: bool,
) -> AppResult<GuestWindowClass> {
    let base = if extended { 4 } else { 0 };
    Ok(match guest_arch {
        GuestArch::X86 => GuestWindowClass {
            style: read_guest_u32(memory, address + base)?,
            wnd_proc: read_guest_u32(memory, address + base + 4)? as u64,
            cls_extra: read_guest_u32(memory, address + base + 8)? as i32,
            wnd_extra: read_guest_u32(memory, address + base + 12)? as i32,
            instance: read_guest_u32(memory, address + base + 16)? as u64,
            icon: read_guest_u32(memory, address + base + 20)? as u64,
            cursor: read_guest_u32(memory, address + base + 24)? as u64,
            background: read_guest_u32(memory, address + base + 28)? as u64,
            menu_name: read_guest_u32(memory, address + base + 32)? as u64,
            class_name_ptr: read_guest_u32(memory, address + base + 36)? as u64,
            icon_small: if extended {
                read_guest_u32(memory, address + base + 40)? as u64
            } else {
                0
            },
        },
        GuestArch::X64 => GuestWindowClass {
            style: read_guest_u32(memory, address + base)?,
            wnd_proc: read_guest_pointer(memory, address + 8, guest_arch)?,
            cls_extra: read_guest_u32(memory, address + 16)? as i32,
            wnd_extra: read_guest_u32(memory, address + 20)? as i32,
            instance: read_guest_pointer(memory, address + 24, guest_arch)?,
            icon: read_guest_pointer(memory, address + 32, guest_arch)?,
            cursor: read_guest_pointer(memory, address + 40, guest_arch)?,
            background: read_guest_pointer(memory, address + 48, guest_arch)?,
            menu_name: read_guest_pointer(memory, address + 56, guest_arch)?,
            class_name_ptr: read_guest_pointer(memory, address + 64, guest_arch)?,
            icon_small: if extended {
                read_guest_pointer(memory, address + 72, guest_arch)?
            } else {
                0
            },
        },
    })
}

fn write_guest_window_class(
    memory: &mut MemoryImage,
    address: u64,
    guest_arch: GuestArch,
    class_info: WindowClassInfo,
    extended: bool,
) -> AppResult<()> {
    match guest_arch {
        GuestArch::X86 => {
            let base = if extended { 4 } else { 0 };
            if extended {
                write_u32(memory, address, 48);
            }
            write_u32(memory, address + base, class_info.style);
            write_u32(memory, address + base + 4, class_info.wnd_proc as u32);
            write_u32(memory, address + base + 8, class_info.cls_extra as u32);
            write_u32(memory, address + base + 12, class_info.wnd_extra as u32);
            write_u32(memory, address + base + 16, class_info.instance as u32);
            write_u32(memory, address + base + 20, class_info.icon as u32);
            write_u32(memory, address + base + 24, class_info.cursor as u32);
            write_u32(memory, address + base + 28, class_info.background as u32);
            write_u32(memory, address + base + 32, class_info.menu_name as u32);
            write_u32(memory, address + base + 36, class_info.class_name_ptr as u32);
            if extended {
                write_u32(memory, address + base + 40, class_info.icon_small as u32);
            }
        }
        GuestArch::X64 => {
            if extended {
                write_u32(memory, address, 80);
                write_u32(memory, address + 4, class_info.style);
                write_guest_pointer(memory, address + 8, class_info.wnd_proc, guest_arch)?;
                write_u32(memory, address + 16, class_info.cls_extra as u32);
                write_u32(memory, address + 20, class_info.wnd_extra as u32);
                write_guest_pointer(memory, address + 24, class_info.instance, guest_arch)?;
                write_guest_pointer(memory, address + 32, class_info.icon, guest_arch)?;
                write_guest_pointer(memory, address + 40, class_info.cursor, guest_arch)?;
                write_guest_pointer(memory, address + 48, class_info.background, guest_arch)?;
                write_guest_pointer(memory, address + 56, class_info.menu_name, guest_arch)?;
                write_guest_pointer(memory, address + 64, class_info.class_name_ptr, guest_arch)?;
                write_guest_pointer(memory, address + 72, class_info.icon_small, guest_arch)?;
            } else {
                write_u32(memory, address, class_info.style);
                write_u32(memory, address + 4, 0);
                write_guest_pointer(memory, address + 8, class_info.wnd_proc, guest_arch)?;
                write_u32(memory, address + 16, class_info.cls_extra as u32);
                write_u32(memory, address + 20, class_info.wnd_extra as u32);
                write_guest_pointer(memory, address + 24, class_info.instance, guest_arch)?;
                write_guest_pointer(memory, address + 32, class_info.icon, guest_arch)?;
                write_guest_pointer(memory, address + 40, class_info.cursor, guest_arch)?;
                write_guest_pointer(memory, address + 48, class_info.background, guest_arch)?;
                write_guest_pointer(memory, address + 56, class_info.menu_name, guest_arch)?;
                write_guest_pointer(memory, address + 64, class_info.class_name_ptr, guest_arch)?;
            }
        }
    }
    Ok(())
}

fn read_c_string(memory: &MemoryImage, address: u64) -> AppResult<String> {
    let bytes = read_c_string_limit(memory, address, usize::MAX)?;
    Ok(String::from_utf8_lossy(&bytes).into_owned())
}

fn read_c_string_limit(memory: &MemoryImage, address: u64, limit: usize) -> AppResult<Vec<u8>> {
    if address == 0 {
        return Ok(Vec::new());
    }
    let mut bytes = Vec::new();
    let mut cursor = address;
    while bytes.len() < limit {
        let byte = memory.read_u8(cursor)?;
        if byte == 0 {
            break;
        }
        bytes.push(byte);
        cursor = cursor.wrapping_add(1);
    }
    Ok(bytes)
}

fn read_utf16_string(memory: &MemoryImage, address: u64) -> AppResult<String> {
    if address == 0 {
        return Ok(String::new());
    }
    let mut code_units = Vec::new();
    let mut cursor = address;
    loop {
        let low = memory.read_u8(cursor)?;
        let high = memory.read_u8(cursor + 1)?;
        let code_unit = u16::from_le_bytes([low, high]);
        if code_unit == 0 {
            break;
        }
        code_units.push(code_unit);
        cursor = cursor.wrapping_add(2);
    }
    Ok(String::from_utf16_lossy(&code_units))
}

fn classify_wide_char_type(info_type: u32, code_unit: u16) -> u16 {
    match info_type {
        CT_CTYPE1 => {
            let Some(ch) = char::from_u32(u32::from(code_unit)) else {
                return 0;
            };
            let mut mask = 0;
            if ch.is_uppercase() {
                mask |= C1_UPPER;
            }
            if ch.is_lowercase() {
                mask |= C1_LOWER;
            }
            if ch.is_numeric() {
                mask |= C1_DIGIT;
            }
            if ch.is_whitespace() {
                mask |= C1_SPACE;
            }
            if ch == ' ' || ch == '\t' {
                mask |= C1_BLANK;
            }
            if ch.is_control() {
                mask |= C1_CNTRL;
            }
            if ch.is_alphabetic() {
                mask |= C1_ALPHA;
            }
            if ch.is_ascii_hexdigit() {
                mask |= C1_XDIGIT;
            }
            if !ch.is_control() && !ch.is_whitespace() && !ch.is_alphanumeric() {
                mask |= C1_PUNCT;
            }
            mask
        }
        CT_CTYPE2 | CT_CTYPE3 => 0,
        _ => 0,
    }
}

fn read_utf16_environment_block(memory: &MemoryImage, address: u64) -> AppResult<BTreeMap<String, String>> {
    let mut cursor = address;
    let mut environment = BTreeMap::new();
    loop {
        let entry = read_utf16_string(memory, cursor)?;
        if entry.is_empty() {
            break;
        }
        if let Some((key, value)) = entry.split_once('=') {
            environment.insert(key.to_string(), value.to_string());
        }
        cursor = cursor.wrapping_add(((entry.encode_utf16().count() + 1) * 2) as u64);
    }
    Ok(environment)
}

/// Read a Win32 ANSI environment block from guest memory.
///
/// The format is a sequence of null-terminated ANSI strings
/// `"KEY=VALUE\0"` terminated by an additional null byte
/// (i.e. double-null terminated overall).
fn read_ansi_environment_block(memory: &MemoryImage, address: u64) -> AppResult<BTreeMap<String, String>> {
    let mut cursor = address;
    let mut environment = BTreeMap::new();
    loop {
        let entry = read_c_string(memory, cursor)?;
        if entry.is_empty() {
            break;
        }
        if let Some((key, value)) = entry.split_once('=') {
            environment.insert(key.to_string(), value.to_string());
        }
        cursor = cursor.wrapping_add((entry.len() + 1) as u64);
    }
    Ok(environment)
}

fn module_file_name(path: &str) -> &str {
    path.rsplit(['\\', '/']).next().unwrap_or(path)
}

fn build_windows_command_line(program: &str, args: &[String]) -> String {
    std::iter::once(program.to_string())
        .chain(args.iter().cloned())
        .map(|arg| {
            if arg.contains([' ', '\t', '"']) {
                format!("\"{}\"", arg.replace('"', "\\\""))
            } else {
                arg
            }
        })
        .collect::<Vec<_>>()
        .join(" ")
}

fn file_access_from_win32(desired_access: u32) -> crate::ge::FileAccess {
    let read_bits = GENERIC_READ
        | GENERIC_ALL
        | FILE_READ_DATA
        | FILE_READ_EA
        | FILE_READ_ATTRIBUTES
        | FILE_EXECUTE;
    let write_bits = GENERIC_WRITE
        | GENERIC_ALL
        | FILE_WRITE_DATA
        | FILE_APPEND_DATA
        | FILE_WRITE_EA
        | FILE_WRITE_ATTRIBUTES
        | FILE_DELETE_CHILD;
    crate::ge::FileAccess {
        read: desired_access & read_bits != 0,
        write: desired_access & write_bits != 0,
        delete: desired_access & (GENERIC_ALL | DELETE_ACCESS | FILE_DELETE_CHILD) != 0,
    }
}

fn share_mode_from_win32(share_mode: u32) -> crate::ge::ShareMode {
    crate::ge::ShareMode {
        read: share_mode & FILE_SHARE_READ != 0,
        write: share_mode & FILE_SHARE_WRITE != 0,
        delete: share_mode & FILE_SHARE_DELETE != 0,
    }
}

fn creation_disposition_from_win32(value: u32) -> AppResult<CreationDisposition> {
    match value {
        CREATE_NEW => Ok(CreationDisposition::CreateNew),
        CREATE_ALWAYS => Ok(CreationDisposition::CreateAlways),
        OPEN_EXISTING => Ok(CreationDisposition::OpenExisting),
        OPEN_ALWAYS => Ok(CreationDisposition::OpenAlways),
        TRUNCATE_EXISTING => Ok(CreationDisposition::TruncateExisting),
        other => Err(AppError::new(
            ReasonCode::RcCliInvalid,
            format!("unsupported CreateFileW disposition {other}"),
        )),
    }
}

fn last_error_from_app_error(error: &AppError) -> u32 {
    match error.code {
        ReasonCode::RcFsNotFound => ERROR_FILE_NOT_FOUND,
        ReasonCode::RcFsPathInvalid => ERROR_PATH_NOT_FOUND,
        ReasonCode::RcWin32InvalidHandle => ERROR_INVALID_HANDLE,
        ReasonCode::RcFsSharingViolation => ERROR_SHARING_VIOLATION,
        ReasonCode::RcFsLockViolation => ERROR_LOCK_VIOLATION,
        ReasonCode::RcFsAlreadyExists => ERROR_ALREADY_EXISTS,
        ReasonCode::RcCliInvalid => ERROR_INVALID_PARAMETER,
        _ => ERROR_ACCESS_DENIED,
    }
}

fn apply_ver_condition_mask(existing_mask: u64, type_mask: u32, condition_mask: u8) -> u64 {
    let mut updated_mask = existing_mask;
    let condition_bits = u64::from(condition_mask & 0x7);
    for bit in [
        VER_MINORVERSION,
        VER_MAJORVERSION,
        VER_BUILDNUMBER,
        VER_PLATFORMID,
        VER_SERVICEPACKMINOR,
        VER_SERVICEPACKMAJOR,
        VER_SUITENAME,
        VER_PRODUCT_TYPE,
    ] {
        if type_mask & bit != 0 {
            let shift = ver_condition_shift(bit).expect("known version type bit");
            updated_mask &= !(0x7_u64 << shift);
            updated_mask |= condition_bits << shift;
        }
    }
    updated_mask
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct GuestVersionInfo {
    major: u32,
    minor: u32,
    build: u32,
    platform_id: u32,
    service_pack_major: u16,
    service_pack_minor: u16,
    suite_mask: u16,
    product_type: u8,
}

fn ver_condition_shift(type_bit: u32) -> Option<u32> {
    match type_bit {
        VER_MINORVERSION => Some(0),
        VER_MAJORVERSION => Some(3),
        VER_BUILDNUMBER => Some(6),
        VER_PLATFORMID => Some(9),
        VER_SERVICEPACKMINOR => Some(12),
        VER_SERVICEPACKMAJOR => Some(15),
        VER_SUITENAME => Some(18),
        VER_PRODUCT_TYPE => Some(21),
        _ => None,
    }
}

fn ver_condition_for_type(condition_mask: u64, type_bit: u32) -> AppResult<u8> {
    let shift = ver_condition_shift(type_bit).ok_or_else(|| {
        AppError::new(
            ReasonCode::RcCliInvalid,
            format!("unsupported version type bit {type_bit:#x}"),
        )
    })?;
    let condition = ((condition_mask >> shift) & 0x7) as u8;
    if condition == 0 {
        return Err(AppError::new(
            ReasonCode::RcCliInvalid,
            format!("missing version condition for type bit {type_bit:#x}"),
        ));
    }
    Ok(condition)
}

