    #[test]
    fn host_thunk_from_import_maps_core_winsock_imports() {
        let ordinal_import = |ordinal: u16| ResolvedImport {
            requested_module: "ws2_32.dll".to_string(),
            resolved_module: "ws2_32.dll".to_string(),
            symbol: ImportSymbol::ByOrdinal { ordinal },
            iat_rva: 0x2000 + ordinal as u32,
            export: ExportSymbol {
                ordinal: ordinal as u32,
                name: None,
                target: ExportTarget::Rva(0x5000 + ordinal as u32),
            },
        };
        let named_import = |name: &str| ResolvedImport {
            requested_module: "ws2_32.dll".to_string(),
            resolved_module: "ws2_32.dll".to_string(),
            symbol: ImportSymbol::ByName {
                hint: 0,
                name: name.to_string(),
            },
            iat_rva: 0x3000,
            export: ExportSymbol {
                ordinal: 1,
                name: Some(name.to_string()),
                target: ExportTarget::Rva(0x6000),
            },
        };

        assert!(matches!(HostThunk::from_import(&ordinal_import(4)), HostThunk::Connect));
        assert!(matches!(HostThunk::from_import(&ordinal_import(10)), HostThunk::Ioctlsocket));
        assert!(matches!(HostThunk::from_import(&ordinal_import(16)), HostThunk::Recv));
        assert!(matches!(HostThunk::from_import(&ordinal_import(19)), HostThunk::Send));
        assert!(matches!(HostThunk::from_import(&ordinal_import(21)), HostThunk::Setsockopt));
        assert!(matches!(HostThunk::from_import(&named_import("getaddrinfo")), HostThunk::Getaddrinfo));
        assert!(matches!(HostThunk::from_import(&named_import("WSARecv")), HostThunk::WsaRecv));
        assert!(matches!(HostThunk::from_import(&named_import("WSASendTo")), HostThunk::WsaSendTo));
    }

