    #[test]
    fn pe_runtime_live_mouse_click_on_preview_button_enqueues_command() {
        let temp_dir = TempDir::new().expect("temp dir");
        let ge = GameEnvironment::create_in(temp_dir.path(), "live-mouse", GeArch::X64, "win11-23h2")
            .expect("create ge");
        let (host_session, pe_session) = crate::live::new_live_session();
        let mut runtime = PeHostRuntime::new(ge, true, Vec::new(), Some(pe_session), None);
        let device_id = runtime
            .live_mouse_device
            .clone()
            .expect("live mouse device registered");

        runtime.user32.register_class_ex_w("LiveMouseInputRoot");
        let root = runtime
            .user32
            .create_window_ex_w(
                "LiveMouseInputRoot",
                "Live Mouse Root",
                400,
                160,
                true,
                false,
                None,
                1,
            )
            .expect("create root window");
        let button = runtime
            .user32
            .create_window_ex_w("BUTTON", "Launch", 75, 25, true, false, Some(root), 1)
            .expect("create child button");
        runtime
            .user32
            .set_window_position(button, 307, 82)
            .expect("position child button");
        runtime
            .user32
            .set_window_control_id(button, 1001)
            .expect("set child control id");
        while runtime.user32.get_message_w().is_some() {}

        host_session
            .input_tx
            .send(LiveInputEvent::MouseInput {
                x: 330,
                y: 126,
                left_pressed: true,
                left_released: false,
            })
            .expect("send left-button press");
        host_session
            .input_tx
            .send(LiveInputEvent::MouseInput {
                x: 330,
                y: 126,
                left_pressed: false,
                left_released: true,
            })
            .expect("send left-button release");
        runtime.poll_live_input().expect("poll live mouse click");

        let mut observed = Vec::new();
        while let Some(message) = runtime.user32.get_message_w() {
            let snapshot = message.clone();
            runtime
                .user32
                .dispatch_message_w(&message)
                .expect("dispatch live mouse message");
            observed.push(snapshot);
        }

        assert!(observed.iter().any(|message| {
            message.kind == MessageKind::LButtonDown
                && message.hwnd == Some(button)
                && message.device_id.as_deref() == Some(device_id.as_str())
        }));
        assert!(observed.iter().any(|message| {
            message.kind == MessageKind::LButtonUp
                && message.hwnd == Some(button)
                && message.device_id.as_deref() == Some(device_id.as_str())
        }));
        assert!(observed.iter().any(|message| {
            message.kind == MessageKind::Command
                && message.hwnd == Some(root)
                && message.wparam == 1001
                && message.lparam == i64::from(button)
        }));
    }

